       specs:[["مقاسات التوصيل","DN80–DN4000 (إدخالي)، DN10–DN2000 (على الأنبوب)"],["السرعة","0.5 ~ 100 متر معياري/ث (20 °م، 101.33 كيلوباسكال)"],["الحساسية","±2.5% (إدخالي) / ±1% (على الأنبوب)"],["حرارة التشغيل","−40…+220 °م (الحساس)، −20…+45 °م (الناقل)"],["أقصى ضغط","الإدخالي ≤2.5 ميجاباسكال، على الأنبوب ≤4.0 ميجاباسكال"],["الخرج","4–20 مللي أمبير (عزل ضوئي إلكتروني، أقصى حمل 500 أوم)"],["خرج الإنذار","1–2 خط ريليه، مفتوح عادةً، 10 أمبير / 220 فولت متردد أو 5 أمبير / 30 فولت مستمر"],["الاتصال","RS485 (عزل ضوئي إلكتروني)، HART"],["درجة الحماية","IP65"]],
       uses:"الهواء الجاف والغازات (البروبان، النيتروجين، الأكسجين، الهيدروجين وغيرها).",
       sectors:"منشآت الطاقة والحرارة، محطات الغاز الطبيعي، الصناعات الكيميائية، صناعة الآلات.",
